{
  "name": "Newport 2832-C双通道光功率计",
  "name_en": "Newport 2832-C Dual-Channel Optical Power Meter",
  "manufacturer": "Newport",
  "description": "Newport 2832-C是一款台式双通道光功率计，用于读取光功率探头或相关探测器通道的测量值。设备支持按波长进行校准设置，并提供外部触发、数据采集与缓冲存储等功能，适合光学实验中进行连续功率监测与记录。",
  "description_en": "The Newport 2832-C is a benchtop dual-channel optical power meter used to read measurements from optical power sensor heads or related detector channels. It supports wavelength-based calibration settings and provides external triggering, data acquisition, and buffered data storage for continuous optical power monitoring and logging in laboratory experiments.",
  "tag_hints": [
    "optical power measurement",
    "dual-channel power meter",
    "wavelength calibration",
    "external trigger",
    "data buffering",
    "photodiode responsivity"
  ],
  "actions": [
    {
      "action_name": "auto-verify_channel",
      "description": "验证所选测量通道是否有效",
      "description_en": "Verify that the selected measurement channel is valid."
    },
    {
      "action_name": "auto-set_rs232_echo",
      "description": "设置RS-232回显状态",
      "description_en": "Set the RS-232 echo state."
    },
    {
      "action_name": "auto-set_wavelength_m",
      "description": "设置测量波长",
      "description_en": "Set the measurement wavelength."
    },
    {
      "action_name": "auto-set_external_trigger",
      "description": "设置外部触发状态",
      "description_en": "Set the external trigger state."
    },
    {
      "action_name": "auto-set_external_trigger_edge",
      "description": "设置外部触发边沿",
      "description_en": "Set the external trigger edge."
    },
    {
      "action_name": "auto-start_data_acquisition",
      "description": "开始数据采集",
      "description_en": "Start data acquisition."
    },
    {
      "action_name": "auto-stop_data_acquisition",
      "description": "停止数据采集",
      "description_en": "Stop data acquisition."
    },
    {
      "action_name": "auto-set_data_store",
      "description": "设置数据存储状态",
      "description_en": "Set the data storage state."
    },
    {
      "action_name": "auto-set_data_buffer_size",
      "description": "设置数据缓冲区大小",
      "description_en": "Set the data buffer size."
    },
    {
      "action_name": "auto-set_data_buffer_units",
      "description": "设置数据缓冲区单位",
      "description_en": "Set the data buffer units."
    },
    {
      "action_name": "auto-clear_data_buffer",
      "description": "清空数据缓冲区",
      "description_en": "Clear the data buffer."
    },
    {
      "action_name": "auto-get_rs232_echo",
      "description": "获取RS-232回显状态",
      "description_en": "Get the RS-232 echo state."
    },
    {
      "action_name": "auto-get_wavelength_m",
      "description": "获取测量波长",
      "description_en": "Get the measurement wavelength."
    },
    {
      "action_name": "auto-get_external_trigger",
      "description": "获取外部触发状态",
      "description_en": "Get the external trigger state."
    },
    {
      "action_name": "auto-get_external_trigger_edge",
      "description": "获取外部触发边沿",
      "description_en": "Get the external trigger edge."
    },
    {
      "action_name": "auto-get_data_store",
      "description": "获取数据存储状态",
      "description_en": "Get the data storage state."
    },
    {
      "action_name": "auto-get_data_buffer_size",
      "description": "获取数据缓冲区大小",
      "description_en": "Get the data buffer size."
    },
    {
      "action_name": "auto-get_data_buffer_units",
      "description": "获取数据缓冲区单位",
      "description_en": "Get the data buffer units."
    },
    {
      "action_name": "auto-get_data_buffer_counts",
      "description": "获取数据缓冲区样本数量",
      "description_en": "Get the number of samples in the data buffer."
    },
    {
      "action_name": "auto-get_data_buffer_sample",
      "description": "获取数据缓冲区指定样本",
      "description_en": "Get a specified sample from the data buffer."
    },
    {
      "action_name": "auto-get_data_buffer_samples",
      "description": "获取数据缓冲区全部样本",
      "description_en": "Get all samples from the data buffer."
    },
    {
      "action_name": "auto-get_responsivity_A_W",
      "description": "获取响应度（A/W）",
      "description_en": "Get the responsivity (A/W)."
    },
    {
      "action_name": "auto-get_range",
      "description": "获取测量量程",
      "description_en": "Get the measurement range."
    },
    {
      "action_name": "auto-get_max_current_A",
      "description": "获取最大电流",
      "description_en": "Get the maximum current."
    },
    {
      "action_name": "auto-get_analogue_current_A",
      "description": "获取与模拟电压对应的电流",
      "description_en": "Get the current corresponding to an analogue voltage."
    }
  ]
}

